skip_unless_full_tests()

# Expected values are SymPy's outputs for the same calls (sympy/solvers/tests/test_simplex.py);
# the rows come from the battery that compares this port with SymPy.

test_that("simplex: test_lp matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", -x - y - 5*z, list(Le(y + 2*z, 3), Le(-x - 3*z, -2), Le(2*x + y + 7*z, 5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-2, {x: 2, y: 0, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(-x - y - 5*z, list(Le(y + 2*z, 3), Le(-x - 3*z, -2), Le(2*x + y + 7*z, 5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-2, {x: 2, y: 0, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("min", -x - y - 5*z, list(Le(y + 2*z, 3), Le(-x - 3*z, -2), Le(2*x + y + 7*z, 5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-11/3, {x: 0, y: 1/3, z: 2/3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(-x - y - 5*z, list(Le(y + 2*z, 3), Le(-x - 3*z, -2), Le(2*x + y + 7*z, 5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-11/3, {x: 0, y: 1/3, z: 2/3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", -x - y - 5*z, list(Le(x - y + 2*z, 3), Le(-x + 2*y - 3*z, -2), Le(2*x + y - 7*z, -5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-25/7, {x: 0, y: 0, z: 5/7})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(-x - y - 5*z, list(Le(x - y + 2*z, 3), Le(-x + 2*y - 3*z, -2), Le(2*x + y - 7*z, -5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-25/7, {x: 0, y: 0, z: 5/7})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("min", -x - y - 5*z, list(Le(x - y + 2*z, 3), Le(-x + 2*y - 3*z, -2), Le(2*x + y - 7*z, -5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-25, {x: 0, y: 5, z: 4})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(-x - y - 5*z, list(Le(x - y + 2*z, 3), Le(-x + 2*y - 3*z, -2), Le(2*x + y - 7*z, -5), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-25, {x: 0, y: 5, z: 4})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", -x - y - 5*z + 2, list(Le(x - y + 2*z, -4), Le(-x + 2*y - 3*z, 8), Le(2*x + y - 7*z, 10), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-2, {x: 0, y: 4, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(-x - y - 5*z + 2, list(Le(x - y + 2*z, -4), Le(-x + 2*y - 3*z, 8), Le(2*x + y - 7*z, 10), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-2, {x: 0, y: 4, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("min", -x - y - 5*z + 2, list(Le(x - y + 2*z, -4), Le(-x + 2*y - 3*z, 8), Le(2*x + y - 7*z, 10), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-2, {x: 0, y: 4, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(-x - y - 5*z + 2, list(Le(x - y + 2*z, -4), Le(-x + 2*y - 3*z, 8), Le(2*x + y - 7*z, 10), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-2, {x: 0, y: 4, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x1 - 2*x2 - 3*x3 - x4, list(Le(x1 - x2 - 2*x3 - x4, 4), Le(2*x1 + x3 - 4*x4, 2), Le(-2*x1 + x2 + x4, 1), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Ge(x4, 0)))) })), "(4, {x1: 7, x2: 0, x3: 0, x4: 3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x1 - 2*x2 - 3*x3 - x4, list(Le(x1 - x2 - 2*x3 - x4, 4), Le(2*x1 + x3 - 4*x4, 2), Le(-2*x1 + x2 + x4, 1), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Ge(x4, 0)))) })), "(4, {x1: 7, x2: 0, x3: 0, x4: 3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("min", x1 - 2*x2 - 3*x3 - x4, list(Le(x1 - x2 - 2*x3 - x4, 4), Le(2*x1 + x3 - 4*x4, 2), Le(-2*x1 + x2 + x4, 1), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Ge(x4, 0)))) })), "ERR UnboundedLPError: \\nObjective function can assume arbitrarily large values!")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 - 2*x2 - 3*x3 - x4, list(Le(x1 - x2 - 2*x3 - x4, 4), Le(2*x1 + x3 - 4*x4, 2), Le(-2*x1 + x2 + x4, 1), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Ge(x4, 0)))) })), "ERR UnboundedLPError: \\nObjective function can assume arbitrarily large values!")
})

test_that("simplex: test_lp_float matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", -x - y - 5*z, list(Le(x - y + Float(2.0)*z, -4), Le(-x + 2*y - Float(3.0)*z, 8), Le(2*x + y - 7*z, 10), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-4, {x: 0, y: 4, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(-x - y - 5*z, list(Le(x - y + Float(2.0)*z, -4), Le(-x + 2*y - Float(3.0)*z, 8), Le(2*x + y - 7*z, 10), Ge(x, 0), Ge(y, 0), Ge(z, 0)))) })), "(-4, {x: 0, y: 4, z: 0})")
})

test_that("simplex: test_lp_err matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", -x - y - 5*z, list(Le(x - y + sqrt(Integer(2))*z, -4), Le(-x + 2*y - 3*z, 8), Le(2*x + y - 7*z, 10)))) })), "ERR TypeError: \\nOnly rationals and floats are allowed.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x, list(Ge(x, 0)))) })), "ERR UnboundedLPError: \\nObjective function can assume arbitrarily large values!")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x, list(Ge(x, 0), Le(x, -1)))) })), "ERR InfeasibleLPError: \\nInconsistent/False constraint")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x, list(Gt(x, 0)))) })), "ERR TypeError: \\nonly equalities like Eq(x, y) or non-strict inequalities like x >= y\\nare allowed in lp, not x > 0")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x, list(Ne(x, 0)))) })), "ERR TypeError: \\nonly equalities like Eq(x, y) or non-strict inequalities like x >= y\\nare allowed in lp, not Ne(x, 0)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x, list(Lt(x + y, 3)))) })), "ERR TypeError: \\nonly equalities like Eq(x, y) or non-strict inequalities like x >= y\\nare allowed in lp, not x + y < 3")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x, list(Le(x, oo)))) })), "ERR ValueError: only finite bounds are permitted")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x, list(Le(x, 2), S_false))) })), "ERR InfeasibleLPError: \\nInconsistent/False constraint")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x, list(Le(x, 2), Le(Integer(1), 0)))) })), "ERR InfeasibleLPError: \\nInconsistent/False constraint")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x, list(Le(x, 2), Ge(y, 3), Le(y, 1)))) })), "ERR InfeasibleLPError: \\nInconsistent/False constraint")
})

test_that("simplex: test_lp_eq matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.lp("max", x, list(Eq(x, y), Eq(y, z), Le(z, 3)))) })), "(3, {x: 3, y: 3, z: 3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x, list(Eq(x, y), Eq(y, z), Le(z, 3)))) })), "(3, {x: 3, y: 3, z: 3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x + y, list(Eq(x, y), Eq(y, z), Ge(z, -3)))) })), "(-6, {x: -3, y: -3, z: -3})")
})

test_that("simplex: test_lp_true matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x, list(Le(x, 2), S_true))) })), "(2, {x: 2})")
})

test_that("simplex: test_simplex matches SymPy", {
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 1), list(-1, 1), list(0, 1), list(-1, 0)), list(5, 1, 2, -1), list(list(-1, -1)), list(1), dual = FALSE)) })), "(-6, [3, 2], [1, 0, 0, 0])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 1), list(-1, 1), list(0, 1), list(-1, 0)), list(5, 1, 2, -1), list(list(-1, -1)), list(1), dual = TRUE)) })), "(-6, [1, 0, 0, 0], [5, 0])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list()), list(), list(list(1)), list(0))) })), "(0, [0], [])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x - y, list(Le(x, y + 2), Ge(x, y + 2), Ge(x, 0), Ge(y, 0)))) })), "(2, {x: 2, y: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x - y, list(Le(x, y + 2), Eq(x, y + 2), Ge(x, 0), Ge(y, 0)))) })), "(2, {x: 2, y: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(x - y, list(Le(x, y + 2), Eq(x, 2)))) })), "(2, {x: 2, y: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(y, list(Eq(y, 2)))) })), "(2, {y: 2})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(y, list(Le(x, y + 2), Ge(x, y + 2), Ge(y, 0)))) })), "(0, {x: 2, y: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(y, list(Le(0, y + 2), Ge(0, y + 2)))) })), "(-2, {y: -2})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(y, list(Le(0, y + 2), Ge(0, y + 2), Le(y, 0)))) })), "(-2, {y: -2})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x, list(Ge(y, 1), Ge(x, y)))) })), "(1, {x: 1, y: 1})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x, list(Ge(y, 1), Ge(x, y + z), Ge(x, 0), Ge(z, 0)))) })), "(1, {x: 1, y: 1, z: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(9*x2 - 8*x3 + 3*x4 + 6, list(Le(5*x2 - 2*x3, 0), Le(-x1 - 8*x2 + 9*x3, -3), Le(10*x1 - x2 + 9*x4, -4), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Ge(x4, 0)))) })), "ERR InfeasibleLPError: \\nThe constraint set is empty!")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(5*x2 + x3 + 4*x4 - x1, list(Le(5*x2 + 2*x3 + 5*x4 - (x1 + 5), 0), Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1), Ge(x1, 0), Le(x1, 1), Ge(x2, 0), Le(x2, 1), Ge(x3, 0), Le(x3, 1), Ge(x4, 0), Le(x4, 1)))) })), "(9/2, {x1: 0, x2: 1/2, x3: 0, x4: 1/2})")
})

test_that("simplex: simplex_extra matches SymPy", {
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 2), list(3, 1)), list(4, 5), list(list(-1, -1)), list(0), dual = FALSE)) })), "(-13/5, [6/5, 7/5], [2/5, 1/5])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 2), list(3, 1)), list(4, 5), list(list(-1, -1)), list(0), dual = TRUE)) })), "(-13/5, [2/5, 1/5], [6/5, 7/5])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 0), list(0, 1)), list(1, 1), list(list(-1, -2)), list(3), dual = FALSE)) })), "(-6, [1, 1], [1, 2])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 0), list(0, 1)), list(1, 1), list(list(-1, -2)), list(3), dual = TRUE)) })), "(-6, [1, 2], [1, 1])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, -1)), list(-2), list(list(1, 1)), list(0), dual = FALSE)) })), "(2, [0, 2], [1])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, -1)), list(-2), list(list(1, 1)), list(0), dual = TRUE)) })), "(2, [1], [0, 2])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(-1, 0)), list(-1), list(list(-1, 0)), list(0), dual = FALSE)) })), "ERR UnboundedLPError: \\nObjective function can assume arbitrarily large values!")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(-1, 0)), list(-1), list(list(-1, 0)), list(0), dual = TRUE)) })), "ERR InfeasibleLPError: \\nThe constraint set is empty!")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(Rational(1, 2), 1), list(1, Rational(1, 3))), list(2, 3), list(list(-3, -2)), list(0), dual = FALSE)) })), "(-48/5, [14/5, 3/5], [6/5, 12/5])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(Rational(1, 2), 1), list(1, Rational(1, 3))), list(2, 3), list(list(-3, -2)), list(0), dual = TRUE)) })), "(-48/5, [6/5, 12/5], [14/5, 3/5])")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 1)), list(-1), list(list(1, 1)), list(0), dual = FALSE)) })), "ERR InfeasibleLPError: \\nThe constraint set is empty!")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 1)), list(-1), list(list(1, 1)), list(0), dual = TRUE)) })), "ERR UnboundedLPError: \\nObjective function can assume arbitrarily large values!")
})

test_that("simplex: simplex_err matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(.simplex(list(list(1, x)), list(1), list(list(1, 1)), list(0))) })), "ERR TypeError: \\nOnly rationals and floats are allowed.")
  expect_identical(.pyrun(local({ .pyT(.simplex(list(list(1, 1)), list(), list(list(1, 1)), list(0))) })), "ERR ValueError: must give A and B")
})

test_that("simplex: test_simplex_linprog matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(linprog(c, a, b, aeq, beq, bounds = list(0, 1))) })), "(9/2, [0, 1/2, 0, 1/2])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(linprog(c, a, b, aeq, beq)) })), "(9/2, [0, 1/2, 0, 1/2])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(linprog(c, a, b)) })), "ERR UnboundedLPError: \\nObjective function can assume arbitrarily large values!")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(linprog(-c, a, b, bounds = list(0, 1))) })), "(-5, [0, 1, 0, 0])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(linprog(c, a, b, aeq, beq, bounds = list(0, 2))) })), "(9/2, [0, 1/2, 0, 1/2])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(linprog(c, a, b, aeq, beq, bounds = list(`0` = list(0, 1), `2` = list(0, 1)))) })), "(9/2, [0, 1/2, 0, 1/2])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(show_linprog(c, a, b, aeq, beq)) })), "(-x1 + 5*x2 + x3 + 4*x4, [-x1 + 5*x2 + 2*x3 + 5*x4 <= 5, Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1), x1 >= 0, x2 >= 0, x3 >= 0, x4 >= 0])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(show_linprog(c, a, b, aeq, beq, bounds = list(0, 1))) })), "(-x1 + 5*x2 + x3 + 4*x4, [-x1 + 5*x2 + 2*x3 + 5*x4 <= 5, Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1), x1 >= 0, x1 <= 1, x2 >= 0, x2 <= 1, x3 >= 0, x3 <= 1, x4 >= 0, x4 <= 1])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); cd <- linear_eq_to_matrix(list(5*x2 + x3 + 4*x4 - x1), list(x1, x2, x3, x4)); c <- cd$A; ab <- linear_eq_to_matrix(list(5*x2 + 2*x3 + 5*x4 - (x1 + 5)), list(x1, x2, x3, x4)); a <- ab$A; b <- ab$b; ae <- linear_eq_to_matrix(list(Eq(3*x2 + x4, 2), Eq(-x1 + x3 + 2*x4, 1)), list(x1, x2, x3, x4)); aeq <- ae$A; beq <- ae$b; .pyT(show_linprog(c, a, b, bounds = list(list(NULL, 1), list(0, NULL), list(1, 2), list(NULL, NULL)))) })), "(-x1 + 5*x2 + x3 + 4*x4, [-x1 + 5*x2 + 2*x3 + 5*x4 <= 5, x1 <= 1, x2 >= 0, x3 >= 1, x3 <= 2])")
})

test_that("simplex: test_lpmin_lpmax matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2, list(Ge(x1 - x2, 1), Ge(x1, 0), Ge(x2, 0)))) })), "(-1, {x1: 1, x2: 0})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(y1 + y2 - 2, list(Le(y1 + y2, 1), Le(-y1 + y2, 1), Ge(y1, 0), Ge(y2, 0)))) })), "(-1, {y1: 1, y2: 0})")
})

test_that("simplex: pd_doc matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 + 7, list(Ge(-x1 + x2, 1), Ge(2*x1 + x2, 3), Ge(x1, 0), Ge(x2, 0)))) })), "(28/3, {x1: 2/3, x2: 5/3})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmax(y1 + 3*y2 + 7, list(Le(-y1 + 2*y2, 1), Le(y1 + y2, 1), Ge(y1, 0), Ge(y2, 0)))) })), "(28/3, {y1: 1/3, y2: 2/3})")
})

test_that("simplex: test_linprog matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); .pyT(linprog(c, ab[[1]], ab[[2]])) })), "(-6/5, [0, 0, 3/5])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0)))) })), "(-6/5, {x1: 0, x2: 0, x3: 3/5})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); .pyT(linprog(c, ab[[1]], ab[[2]], abeq[[1]], abeq[[2]])) })), "(-2/5, [0, 1, 7/10])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3 + 1, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Eq(x2 - 9*x1, 1)))) })), "(3/5, {x1: 0, x2: 1, x3: 7/10})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); abeq <- linear_eq_to_matrix(list(x3 - x2 - Rational(1, 2)), list(x1, x2, x3)); .pyT(linprog(c, ab[[1]], ab[[2]], abeq[[1]], abeq[[2]])) })), "(-10/9, [0, 1/9, 11/18])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3 + 1, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Le(x3 - x2, Rational(1, 2))))) })), "(-1/9, {x1: 0, x2: 1/9, x3: 11/18})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3 + 1, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Le(x3, Rational(1, 2))))) })), "(0, {x1: 0, x2: 0, x3: 1/2})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); .pyT(linprog(c, ab[[1]], ab[[2]], bounds = list(list(0, NULL), list(0, NULL), list(NULL, Rational(1, 2))))) })), "(-1, [0, 0, 1/2])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); .pyT(linprog(c, ab[[1]], ab[[2]], bounds = list(`2` = list(NULL, Rational(1, 2))))) })), "(-1, [0, 0, 1/2])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- .mrows(c); ab <- lapply(ab, .mrows); .pyT(linprog(c, ab[[1]], ab[[2]])) })), "(-6/5, [0, 0, 3/5])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0)))) })), "(-6/5, {x1: 0, x2: 0, x3: 3/5})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- .mrows(c); ab <- lapply(ab, .mrows); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); c <- .mrows(c); abeq <- lapply(abeq, .mrows); .pyT(linprog(c, ab[[1]], ab[[2]], abeq[[1]], abeq[[2]])) })), "(-2/5, [0, 1, 7/10])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3 + 1, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Eq(x2 - 9*x1, 1)))) })), "(3/5, {x1: 0, x2: 1, x3: 7/10})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- .mrows(c); ab <- lapply(ab, .mrows); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); c <- .mrows(c); abeq <- lapply(abeq, .mrows); abeq <- linear_eq_to_matrix(list(x3 - x2 - Rational(1, 2)), list(x1, x2, x3)); abeq <- lapply(abeq, .mrows); .pyT(linprog(c, ab[[1]], ab[[2]], abeq[[1]], abeq[[2]])) })), "(-10/9, [0, 1/9, 11/18])")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3 + 1, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Le(x3 - x2, Rational(1, 2))))) })), "(-1/9, {x1: 0, x2: 1/9, x3: 11/18})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); .pyT(lpmin(x1 + x2 - 2*x3 + 1, list(Le(7*x1 + 4*x2 - 7*x3, 3), Le(3*x1 - x2 + 10*x3, 6), Ge(x1, 0), Ge(x2, 0), Ge(x3, 0), Le(x3, Rational(1, 2))))) })), "(0, {x1: 0, x2: 0, x3: 1/2})")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); x1 <- Symbol("x1"); x2 <- Symbol("x2"); x3 <- Symbol("x3"); x4 <- Symbol("x4"); y1 <- Symbol("y1"); y2 <- Symbol("y2"); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3), list(x1, x2, x3))$A; ab <- linear_eq_to_matrix(list(7*x1 + 4*x2 - 7*x3 - 3, 3*x1 - x2 + 10*x3 - 6, -x1, -x2, -x3), list(x1, x2, x3)); c <- .mrows(c); ab <- lapply(ab, .mrows); c <- linear_eq_to_matrix(list(x1 + x2 - 2*x3 + 1), list(x1, x2, x3))$A; abeq <- linear_eq_to_matrix(list(x2 - 9*x1 - 1), list(x1, x2, x3)); c <- .mrows(c); abeq <- lapply(abeq, .mrows); .pyT(linprog(c, ab[[1]], ab[[2]], bounds = list(list(0, NULL), list(0, NULL), list(NULL, Rational(1, 2))))) })), "(-1, [0, 0, 1/2])")
