  expect_identical(.pyrun(local({ .pyT(linprog(list(1, -1), bounds = list(-2, 3))) })), "(-3, [0, 3])")
  expect_identical(.pyrun(local({ .pyT(show_linprog(list(1, -1), list(list(1, 1)), list(2), bounds = list(`1` = list(NULL, NULL)))) })), "(x1 - x2, [x1 + x2 <= 2, x1 >= 0])")
  expect_identical(.pyrun(local({ .pyT(show_linprog(list(1, 2))) })), "(x1 + 2*x2, [x1 >= 0, x2 >= 0])")
  expect_identical(.pyrun(local({ .pyT(show_linprog(list(1, 2), list(list(1, 1)), list(3), list(list(1, -1)), list(0))) })), "(x1 + 2*x2, [x1 + x2 <= 3, Eq(x1 - x2, 0), x1 >= 0, x2 >= 0])")
